CREATE TRIGGER protect_private_feedback_owner BEFORE UPDATE ON private_feedback FOR EACH ROW
BEGIN
IF NOT (BINARY OLD.id<=>BINARY NEW.id) OR NOT (BINARY OLD.public_id<=>BINARY NEW.public_id) OR NOT (BINARY OLD.tenant_id<=>BINARY NEW.tenant_id) OR NOT (BINARY OLD.branch_id<=>BINARY NEW.branch_id) OR NOT (BINARY OLD.funnel_configuration_id<=>BINARY NEW.funnel_configuration_id) OR NOT (BINARY OLD.industry_channel_id<=>BINARY NEW.industry_channel_id) OR NOT (BINARY OLD.short_link_id<=>BINARY NEW.short_link_id) OR NOT (BINARY OLD.submission_key_hash<=>BINARY NEW.submission_key_hash) OR NOT (BINARY OLD.overall_rating<=>BINARY NEW.overall_rating) OR NOT (BINARY OLD.service_rating<=>BINARY NEW.service_rating) OR NOT (BINARY OLD.cleanliness_rating<=>BINARY NEW.cleanliness_rating) OR NOT (BINARY OLD.waiting_time_rating<=>BINARY NEW.waiting_time_rating) OR NOT (BINARY OLD.submitted_at<=>BINARY NEW.submitted_at) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Immutable record ownership'; END IF;
END
